public class InnerDataAutomationProjectOverrideConfigurationFactory(Action<Humidifier.Bedrock.DataAutomationProjectTypes.OverrideConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.Bedrock.DataAutomationProjectTypes.OverrideConfiguration>
{

    internal InnerDataAutomationProjectVideoOverrideConfigurationFactory VideoFactory { get; set; }

    internal InnerDataAutomationProjectModalityRoutingConfigurationFactory ModalityRoutingFactory { get; set; }

    internal InnerDataAutomationProjectDocumentOverrideConfigurationFactory DocumentFactory { get; set; }

    internal InnerDataAutomationProjectAudioOverrideConfigurationFactory AudioFactory { get; set; }

    internal InnerDataAutomationProjectImageOverrideConfigurationFactory ImageFactory { get; set; }

    protected override Humidifier.Bedrock.DataAutomationProjectTypes.OverrideConfiguration Create()
    {
        var overrideConfigurationResult = CreateOverrideConfiguration();
        factoryAction?.Invoke(overrideConfigurationResult);

        return overrideConfigurationResult;
    }

    private Humidifier.Bedrock.DataAutomationProjectTypes.OverrideConfiguration CreateOverrideConfiguration()
    {
        var overrideConfigurationResult = new Humidifier.Bedrock.DataAutomationProjectTypes.OverrideConfiguration();

        return overrideConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Bedrock.DataAutomationProjectTypes.OverrideConfiguration result)
    {
        base.CreateChildren(result);

        result.Video ??= VideoFactory?.Build();
        result.ModalityRouting ??= ModalityRoutingFactory?.Build();
        result.Document ??= DocumentFactory?.Build();
        result.Audio ??= AudioFactory?.Build();
        result.Image ??= ImageFactory?.Build();
    }

} // End Of Class

